fun lengthOfLongestSubstring(s: String): Int {
    val lastSeen = HashMap<Char, Int>()
    var left = 0
    var best = 0

    for (right in s.indices) {
        val c = s[right]
        // only jump forward — never move left backwards
        lastSeen[c]?.let { prev -> if (prev >= left) left = prev + 1 }
        lastSeen[c] = right
        best = maxOf(best, right - left + 1)
    }
    return best
}

