class LRUCache<K, V>(private val capacity: Int) {

    private class Node<K, V>(val key: K, var value: V) {
        var prev: Node<K, V>? = null
        var next: Node<K, V>? = null
    }

    private val map = HashMap<K, Node<K, V>>()
    private val head = Node<K, V>(null as K, null as V)   // sentinels avoid null checks
    private val tail = Node<K, V>(null as K, null as V)

    init { head.next = tail; tail.prev = head }

    fun get(key: K): V? {
        val node = map[key] ?: return null
        moveToFront(node)
        return node.value
    }

    fun put(key: K, value: V) {
        map[key]?.let { it.value = value; moveToFront(it); return }

        if (map.size == capacity) {
            val lru = tail.prev!!
            unlink(lru)
            map.remove(lru.key)
        }
        val node = Node(key, value)
        map[key] = node
        addFirst(node)
    }

    private fun moveToFront(n: Node<K, V>) { unlink(n); addFirst(n) }

    private fun unlink(n: Node<K, V>) {
        n.prev?.next = n.next
        n.next?.prev = n.prev
    }

    private fun addFirst(n: Node<K, V>) {
        n.next = head.next
        n.prev = head
        head.next?.prev = n
        head.next = n
    }
}

class SimpleLru<K, V>(private val capacity: Int) :
    LinkedHashMap<K, V>(capacity, 0.75f, /* accessOrder = */ true) {
    override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>) = size > capacity
}

