class SearchViewModel(private val repo: SearchRepository) : ViewModel() {

    private val query = MutableStateFlow("")

    val state: StateFlow<SearchUiState> = query
        .debounce(300)                      // wait for typing to settle
        .map { it.trim() }
        .distinctUntilChanged()             // ignore no-op edits
        .flatMapLatest { q ->               // CANCELS the previous request
            if (q.length < 2) {
                flowOf(SearchUiState.Idle)
            } else {
                repo.search(q)
                    .map<List<Item>, SearchUiState> { SearchUiState.Results(it) }
                    .onStart { emit(SearchUiState.Loading) }
                    // catch INSIDE the inner flow: one failed search must not
                    // terminate the outer flow for the rest of the session
                    .catch { emit(SearchUiState.Error(it)) }
            }
        }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), SearchUiState.Idle)

    fun onQueryChange(q: String) { query.value = q }
}

sealed interface SearchUiState {
    data object Idle : SearchUiState
    data object Loading : SearchUiState
    data class Results(val items: List<Item>) : SearchUiState
    data class Error(val cause: Throwable) : SearchUiState
}

