fun rob(nums: IntArray): Int {
    var skip = 0    // best if we do NOT take the previous house  (dp[i-2])
    var take = 0    // best considering everything up to previous (dp[i-1])

    for (n in nums) {
        val next = maxOf(take, skip + n)
        skip = take
        take = next
    }
    return take
}

fun robTable(nums: IntArray): Int {
    if (nums.isEmpty()) return 0
    if (nums.size == 1) return nums[0]

    val dp = IntArray(nums.size)
    dp[0] = nums[0]
    dp[1] = maxOf(nums[0], nums[1])
    for (i in 2 until nums.size) {
        dp[i] = maxOf(dp[i - 1], dp[i - 2] + nums[i])
    }
    return dp.last()
}

